interface Button { render(): void }
interface Checkbox { check(): void }
interface UIFactory { createButton(): Button; createCheckbox(): Checkbox }
class LightFactory implements UIFactory { createButton() { return new LightButton() } createCheckbox() { return new LightCheckbox() } }
class DarkFactory implements UIFactory { createButton() { return new DarkButton() } createCheckbox() { return new DarkCheckbox() } }
function renderUI(factory: UIFactory) { const b = factory.createButton(); b.render() }

// Version A: client chooses concrete factories directly
function createButton(theme: string): Button {
  if (theme === 'dark') return new DarkButton()
  return new LightButton()
}

// Version B: client receives a factory implementing the family creator interface
interface UIFactory { createButton(): Button }
function renderUI(factory: UIFactory) {
  const btn = factory.createButton()
  btn.render()
}
